/**
 * Assemble the release body for one version from CHANGELOG.md.
 *
 * The Chinese release notes are written by hand, one `## v<version>` section
 * per release, newest first. This script picks that section and appends the
 * install snippet; the changelogithub output (the English conventional-commit
 * detail) is not included — the release page keeps it in GitHub's own
 * autogenerated section below the notes.
 *
 * A version missing from CHANGELOG.md is not an error: the script then passes
 * the changelogithub notes through unchanged, so a forgotten entry degrades
 * to the previous behaviour instead of breaking the release.
 *
 * Usage:
 *   node scripts/release-notes.mjs --version 0.7.0 \
 *     [--cl-notes <path>] [--changelog <path>] [--out <path>]
 *
 * `--cl-notes` is accepted for workflow compatibility and ignored: the step
 * that generates it stays in the pipeline (its run also validates the token
 * and the commit range), but its output no longer feeds the body.
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { pathToFileURL } from 'node:url'

/** Parse `--key value` pairs from argv into a plain map. */
function argsOf(argv) {
  const args = {}
  for (let i = 0; i < argv.length; i++) {
    if (!argv[i].startsWith('--')) continue
    const key = argv[i].slice(2)
    const next = argv[i + 1]
    if (next !== undefined && !next.startsWith('--')) {
      args[key] = next
      i++
    } else {
      args[key] = ''
    }
  }
  return args
}

/**
 * Extract one version's section text from the changelog.
 *
 * Matches `## v<version>` or `## <version>` exactly — no prefix matching, so
 * a `v0.7` heading can never swallow `0.7.1`'s notes. The section runs to the
 * next `## ` heading or end of file; the heading itself is dropped.
 * @returns the section body, or null when the changelog has no such version.
 */
export function sectionFor(changelogText, version) {
  const lines = changelogText.split('\n')
  const headings = [`## v${version}`, `## ${version}`]
  let start = -1
  for (let i = 0; i < lines.length; i++) {
    if (headings.includes(lines[i].trim())) {
      start = i + 1
      break
    }
  }
  if (start === -1) return null
  let end = lines.length
  for (let i = start; i < lines.length; i++) {
    if (lines[i].startsWith('## ')) {
      end = i
      break
    }
  }
  const body = lines.slice(start, end).join('\n').replace(/^\s*\n+/, '').replace(/\s+$/, '')
  return body.length > 0 ? body : null
}

const INSTALL_SNIPPET = `

## Install

\`\`\`sh
dsh plugin --profile web add dsh-magpie-connect
\`\`\`

The same command updates an existing installation to the latest version; restart \`dsh web\` after installing.`

// Run the CLI body only when executed directly, so the section extractor can
// be imported (and tested) without the `--version` requirement firing.
const invokedDirectly = process.argv[1] !== undefined
  && import.meta.url === pathToFileURL(process.argv[1]).href

if (invokedDirectly) {
  const args = argsOf(process.argv.slice(2))
  const version = args.version ?? ''
  if (version === '' || version === undefined) {
    console.error('release-notes: --version is required')
    process.exit(1)
  }
  // The tag may arrive as `v0.7.0`; the changelog headings match either spelling.
  const bare = version.replace(/^v/, '')

  const changelogPath = args.changelog ?? 'CHANGELOG.md'
  let changelogText = ''
  try {
    changelogText = readFileSync(changelogPath, 'utf8')
  } catch {
    // No changelog at all: pass-through, same as a missing section.
    changelogText = ''
  }
  const section = sectionFor(changelogText, version) ?? sectionFor(changelogText, bare)

  const body = (section ?? '') + INSTALL_SNIPPET + '\n'
  if (args.out) {
    writeFileSync(args.out, body, 'utf8')
    console.log(`release-notes: wrote ${args.out} (${section === null ? 'passthrough, version not in changelog' : 'changelog section v' + bare}, ${body.length} bytes)`)
  } else {
    process.stdout.write(body)
  }
}
